"use client";

import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { ArrowUpRight } from 'lucide-react';

export default function Hero() {
  const [currentSlide, setCurrentSlide] = useState(0);

  const slides = [
  {
    image: "/images/banner5.avif",
    title: "Welcome to Accessibility Support",
    subtitle: "Submit requests for exam adjustments, interpreters, transportation, and specialized academic support",
    buttonText: "Submit Accommodation Request",
    align: "center",
    bgColor: "bg-gradient-to-r from-blue-600/90 via-blue-700/90 to-indigo-800/90",
    buttonStyle: "bg-white text-blue-700 hover:bg-blue-50 font-bold px-8 py-3 rounded-lg shadow-lg"
  },
  {
    image: "/images/banner4.avif",
    title: "Streamlined Digital Process",
    subtitle: "Automated routing to relevant departments • Real-time tracking • Quick approval process",
    buttonText: "Track Your Request Status",
    align: "left",
    bgColor: "bg-gradient-to-r from-emerald-600/90 via-teal-700/90 to-cyan-800/90",
    buttonStyle: "bg-white text-emerald-700 hover:bg-emerald-50 font-bold px-8 py-3 rounded-lg shadow-lg"
  },
  {
    image: "/images/banner3.avif",
    title: "Personalized Support Services",
    subtitle: "Working together to create customized accommodation plans for your academic success",
    buttonText: "Explore Support Services",
    align: "right",
    bgColor: "bg-gradient-to-r from-purple-600/90 via-violet-700/90 to-fuchsia-800/90",
    buttonStyle: "bg-white text-purple-700 hover:bg-purple-50 font-bold px-8 py-3 rounded-lg shadow-lg"
  }
  ];

  // Auto slide functionality
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentSlide((prev) => (prev === slides.length - 1 ? 0 : prev + 1));
    }, 5000);

    return () => clearInterval(interval);
  }, [slides.length]);

  // Go to specific slide
  const goToSlide = (index) => {
    setCurrentSlide(index);
  };

  // Next slide
  const nextSlide = () => {
    setCurrentSlide((prev) => (prev === slides.length - 1 ? 0 : prev + 1));
  };

  // Previous slide
  const prevSlide = () => {
    setCurrentSlide((prev) => (prev === 0 ? slides.length - 1 : prev - 1));
  };

  return (
    <div className="relative w-full h-[600px] overflow-hidden">
      {/* Slides Container */}
      <div className="relative w-full h-full">
        {slides.map((slide, index) => (
          <div
            key={index}
            className={`absolute inset-0 transition-all duration-1000 ease-in-out ${
              index === currentSlide
                ? 'opacity-100 z-10'
                : 'opacity-0 z-0'
            }`}
          >
            {/* Background Image */}
            <div className="absolute inset-0">
              <Image
                src={slide.image}
                alt={slide.title}
                fill
                priority={index === 0}
                className="object-cover"
                sizes="100vw"
              />
              {/* Dark overlay for better text readability */}
              <div className={`absolute inset-0 ${slide.bgColor}`}></div>
            </div>

            {/* Content */}
            <div className={`relative h-full flex items-center ${
              slide.align === 'center' 
                ? 'justify-center text-center' 
                : slide.align === 'left' 
                ? 'justify-start pl-8 md:pl-16 lg:pl-24' 
                : 'justify-end pr-8 md:pr-16 lg:pr-24'
            }`}>
              <div className="max-w-2xl text-white px-4">
                <h1 className="text-4xl md:text-5xl lg:text-6xl font-bold mb-4 leading-tight">
                  {slide.title}
                </h1>
                <p className="text-xl md:text-2xl mb-8 opacity-95">
                  {slide.subtitle}
                </p>
                <Link href="/library">
                  <button className="group px-6 py-3 bg-white text-primary rounded-lg hover:bg-gray-100 transition-all duration-300 font-medium text-lg flex items-center gap-2 shadow-lg hover:shadow-xl transform hover:-translate-y-1">
                    {slide.buttonText}
                    <ArrowUpRight className="w-5 h-5 group-hover:translate-x-1 group-hover:-translate-y-1 transition-transform duration-300" />
                  </button>
                </Link>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Navigation Dots */}
      <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 z-20 flex gap-3">
        {slides.map((_, index) => (
          <button
            key={index}
            onClick={() => goToSlide(index)}
            className={`w-3 h-3 rounded-full transition-all duration-300 ${
              index === currentSlide 
                ? 'bg-white scale-125' 
                : 'bg-white/50 hover:bg-white/80'
            }`}
            aria-label={`Go to slide ${index + 1}`}
          />
        ))}
      </div>

      {/* Navigation Arrows */}
      <button
        onClick={prevSlide}
        className="absolute left-4 md:left-8 top-1/2 transform -translate-y-1/2 z-20 w-10 h-10 md:w-12 md:h-12 rounded-full bg-white/10 hover:bg-white/20 backdrop-blur-sm flex items-center justify-center text-white transition-all duration-300 group"
        aria-label="Previous slide"
      >
        <svg className="w-5 h-5 md:w-6 md:h-6 transform group-hover:-translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7" />
        </svg>
      </button>

      <button
        onClick={nextSlide}
        className="absolute right-4 md:right-8 top-1/2 transform -translate-y-1/2 z-20 w-10 h-10 md:w-12 md:h-12 rounded-full bg-white/10 hover:bg-white/20 backdrop-blur-sm flex items-center justify-center text-white transition-all duration-300 group"
        aria-label="Next slide"
      >
        <svg className="w-5 h-5 md:w-6 md:h-6 transform group-hover:translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7" />
        </svg>
      </button>

      {/* Slide Counter */}
      <div className="absolute bottom-14 right-8 z-20 text-white/80 text-sm hidden md:block">
        {currentSlide + 1} / {slides.length}
      </div>

      {/* Scroll Indicator */}
      <div className="absolute bottom-0 left-1/2 transform -translate-x-1/2 z-20 animate-bounce">
        <svg className="w-6 h-6 text-white/80" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 14l-7 7m0 0l-7-7m7 7V3" />
        </svg>
      </div>
    </div>
  );
}